from fastapi import APIRouter, Depends
from sqlalchemy.orm import Session
from sqlalchemy import func
from typing import List, Optional

from database import get_db
import models
import schemas

router = APIRouter(prefix="/defects", tags=["Defects & Metrology"])

@router.post("/", response_model=schemas.DefectResponse)
def log_defect(defect_in: schemas.DefectCreate, db: Session = Depends(get_db)):
    """Log an analytical defect generated by physics or consequence rule violation."""
    defect = models.DefectRecord(
        session_id=defect_in.session_id,
        wafer_id=defect_in.wafer_id,
        defect_id=defect_in.defect_id,
        defect_type=defect_in.defect_type,
        severity=defect_in.severity,
        is_critical=defect_in.is_critical,
        origin_equipment=defect_in.origin_equipment,
        pos_x=defect_in.pos_x,
        pos_y=defect_in.pos_y,
        pos_z=defect_in.pos_z
    )
    db.add(defect)
    db.commit()
    db.refresh(defect)
    return defect

@router.get("/", response_model=List[schemas.DefectResponse])
def get_defects(wafer_id: Optional[str] = None, skip: int = 0, limit: int = 50, db: Session = Depends(get_db)):
    """List logged defects, optionally filtered by wafer ID."""
    q = db.query(models.DefectRecord)
    if wafer_id:
        q = q.filter(models.DefectRecord.wafer_id == wafer_id)
    return q.order_by(models.DefectRecord.timestamp.desc()).offset(skip).limit(limit).all()

@router.get("/summary", response_model=schemas.DefectSummary)
def get_defect_summary(session_id: Optional[str] = None, db: Session = Depends(get_db)):
    """Compute defect taxonomy aggregation and Murphy yield prediction."""
    q = db.query(models.DefectRecord)
    if session_id:
        q = q.filter(models.DefectRecord.session_id == session_id)
    
    all_defects = q.all()
    total = len(all_defects)
    critical = sum(1 for d in all_defects if d.is_critical or d.severity >= 0.75)

    by_type = {}
    by_tool = {}
    for d in all_defects:
        by_type[d.defect_type] = by_type.get(d.defect_type, 0) + 1
        by_tool[d.origin_equipment] = by_tool.get(d.origin_equipment, 0) + 1

    # Murphy model estimate: Y = ((1 - exp(-D*A))/(D*A))^2 with normalized defect density
    # Simplified yield estimate for student feedback:
    if total == 0:
        yield_pct = 100.0
    else:
        yield_pct = max(0.0, 100.0 - (critical * 25.0 + (total - critical) * 8.0))

    return schemas.DefectSummary(
        total_defects=total,
        critical_defects=critical,
        yield_estimate_percentage=round(yield_pct, 2),
        defects_by_type=by_type,
        defects_by_equipment=by_tool
    )
